input.script:
export const meta = {
  name: 'centre-the-bestiary',
  description: 'Measure and centre every drollery in its cell',
  phases: [{ title: 'Measure' }, { title: 'Verify' }],
}

const CREATURES = args ?? []

const nudges = await pipeline(
  CREATURES,
  name => agent(`Measure the bbox of ${name}.svg in a 90x210 cell`, {phase: 'Measure'}),
  (bbox, name) => agent(`Verify ${name} centres on (45, 105)`, {phase: 'Verify'}),
)

return nudges.filter(Boolean)
